function createRipple(e){const t=e.currentTarget,o=document.createElement("span"),l=Math.max(t.clientWidth,t.clientHeight),c=l/2;Object.assign(o.style,{width:`${l}px`,height:`${l}px`,left:e.offsetX-c+"px",top:e.offsetY-c+"px"}),o.classList.add("ripple"),t.querySelector(".ripple")?.remove(),t.appendChild(o)}for(const e of document.querySelectorAll("button[data-ripple]"))e.classList.contains("tooltip")||e.addEventListener("click",createRipple);for(const e of document.querySelectorAll("button[data-modal]"))e.addEventListener("click",()=>{document.getElementById(e.dataset.modal)?.showModal()});for(const e of document.querySelectorAll(".close-btn"))e.addEventListener("click",()=>{e.closest("dialog")?.close()});for(const e of document.querySelectorAll("dialog.modal"))e.addEventListener("click",t=>{t.target===e&&e.close()});